#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <string.h>

typedef long long lapack_int64;

extern lapack_int64 scipy_LAPACKE_dgeev_work64_(
    int matrix_layout, char jobvl, char jobvr, lapack_int64 n,
    double* a, lapack_int64 lda, double* wr, double* wi,
    double* vl, lapack_int64 ldvl, double* vr, lapack_int64 ldvr,
    double* work, lapack_int64 lwork);

#define LAPACK_ROW_MAJOR 101

static PyObject* dominant(PyObject* self, PyObject* arg) {
    PyArrayObject* arr = (PyArrayObject*)PyArray_FROM_OTF(arg, NPY_DOUBLE,
        NPY_ARRAY_C_CONTIGUOUS | NPY_ARRAY_ALIGNED);
    if (!arr) return NULL;
    if (PyArray_NDIM(arr) != 2 || PyArray_DIM(arr,0) != PyArray_DIM(arr,1)) {
        Py_DECREF(arr);
        PyErr_SetString(PyExc_ValueError, "expected square matrix");
        return NULL;
    }
    npy_intp n = PyArray_DIM(arr,0);
    if (n < 1 || n > 64) {
        Py_DECREF(arr);
        PyErr_SetString(PyExc_ValueError, "unsupported size");
        return NULL;
    }
    double a[64*64];
    double wr[64], wi[64], vr[64*64], work[8192];
    double vl[1];
    memcpy(a, PyArray_DATA(arr), (size_t)n*n*sizeof(double));
    Py_DECREF(arr);

    lapack_int64 info = scipy_LAPACKE_dgeev_work64_(
        LAPACK_ROW_MAJOR, 'N', 'V', (lapack_int64)n,
        a, (lapack_int64)n, wr, wi,
        vl, 1, vr, (lapack_int64)n, work, 8192);
    if (info != 0) {
        PyErr_SetString(PyExc_RuntimeError, "LAPACK dgeev failed");
        return NULL;
    }
    npy_intp best = 0;
    double bestabs = hypot(wr[0], wi[0]);
    for (npy_intp i=1; i<n; i++) {
        double ab = hypot(wr[i], wi[i]);
        if (ab > bestabs) { bestabs = ab; best = i; }
    }
    PyObject* val = PyComplex_FromDoubles(wr[best], wi[best]);
    if (!val) return NULL;
    npy_intp dims[1] = {n};
    PyArrayObject* vec = (PyArrayObject*)PyArray_SimpleNew(1, dims, NPY_COMPLEX128);
    if (!vec) { Py_DECREF(val); return NULL; }
    npy_cdouble* out = (npy_cdouble*)PyArray_DATA(vec);
    if (wi[best] == 0.0) {
        for (npy_intp i=0; i<n; i++) {
            double re = vr[i*n + best];
            out[i] = npy_cpack(re, 0.0);
        }
    } else {
        npy_intp j = (wi[best] > 0.0) ? best : best-1;
        double sign = (wi[best] > 0.0) ? 1.0 : -1.0;
        for (npy_intp i=0; i<n; i++) {
            double re = vr[i*n + j];
            double im = sign * vr[i*n + j + 1];
            out[i] = npy_cpack(re, im);
        }
    }
    PyObject* res = PyTuple_Pack(2, val, (PyObject*)vec);
    Py_DECREF(val);
    Py_DECREF(vec);
    return res;
}

static PyMethodDef Methods[] = {
    {"dominant", dominant, METH_O, "dominant eigenpair"},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "eigfast", NULL, -1, Methods,
    NULL, NULL, NULL, NULL
};
PyMODINIT_FUNC PyInit_eigfast(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
