#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <string.h>

/* NumPy ships OpenBLAS built with 64-bit integers.  Call its Fortran
 * interface directly to avoid the Python/numpy.linalg dispatch overhead. */
typedef long long lapack_int64;
extern void scipy_dgeev_64_(
    const char* jobvl, const char* jobvr, const lapack_int64* n,
    double* a, const lapack_int64* lda, double* wr, double* wi,
    double* vl, const lapack_int64* ldvl, double* vr, const lapack_int64* ldvr,
    double* work, const lapack_int64* lwork, lapack_int64* info);

#define MAX_N 64

static PyObject* dominant(PyObject* self, PyObject* arg) {
    PyArrayObject* arr = (PyArrayObject*)PyArray_FROM_OTF(
        arg, NPY_DOUBLE, NPY_ARRAY_C_CONTIGUOUS | NPY_ARRAY_ALIGNED);
    if (arr == NULL) return NULL;

    if (PyArray_NDIM(arr) != 2 ||
        PyArray_DIM(arr, 0) != PyArray_DIM(arr, 1)) {
        Py_DECREF(arr);
        PyErr_SetString(PyExc_ValueError, "expected a square matrix");
        return NULL;
    }

    npy_intp n = PyArray_DIM(arr, 0);
    if (n < 1 || n > MAX_N) {
        Py_DECREF(arr);
        PyErr_SetString(PyExc_ValueError, "unsupported matrix size");
        return NULL;
    }

    /* LAPACK wants column-major input.  Copy the (small) matrix to a local
     * Fortran-order buffer; the caller's array is never modified. */
    const double* src = (const double*)PyArray_DATA(arr);
    double a[MAX_N * MAX_N];
    for (npy_intp j = 0; j < n; ++j) {
        for (npy_intp i = 0; i < n; ++i) {
            a[j * n + i] = src[i * n + j];
        }
    }
    Py_DECREF(arr);

    double wr[MAX_N], wi[MAX_N];
    double vr[MAX_N * MAX_N];
    double vl[1];
    double work[8192];

    lapack_int64 nn = (lapack_int64)n;
    lapack_int64 lda = nn, ldvl = 1, ldvr = nn;
    lapack_int64 lwork = 8192, info = 0;

    scipy_dgeev_64_("N", "V", &nn, a, &lda, wr, wi,
                    vl, &ldvl, vr, &ldvr, work, &lwork, &info);
    if (info != 0) {
        PyErr_SetString(PyExc_RuntimeError, "LAPACK dgeev failed");
        return NULL;
    }

    /* Pick the eigenvalue with the largest magnitude. */
    npy_intp best = 0;
    double best_abs2 = wr[0] * wr[0] + wi[0] * wi[0];
    for (npy_intp i = 1; i < n; ++i) {
        double abs2 = wr[i] * wr[i] + wi[i] * wi[i];
        if (abs2 > best_abs2) {
            best_abs2 = abs2;
            best = i;
        }
    }

    PyObject* value = PyComplex_FromDoubles(wr[best], wi[best]);
    if (value == NULL) return NULL;

    npy_intp dims[1] = {n};
    PyArrayObject* vec = (PyArrayObject*)PyArray_SimpleNew(
        1, dims, NPY_COMPLEX128);
    if (vec == NULL) {
        Py_DECREF(value);
        return NULL;
    }

    /* dgeev packs a complex-conjugate pair into two adjacent real columns. */
    double* out = (double*)PyArray_DATA(vec);
    if (wi[best] == 0.0) {
        for (npy_intp i = 0; i < n; ++i) {
            out[2 * i] = vr[best * n + i];
            out[2 * i + 1] = 0.0;
        }
    } else {
        npy_intp j = (wi[best] > 0.0) ? best : best - 1;
        double sign = (wi[best] > 0.0) ? 1.0 : -1.0;
        for (npy_intp i = 0; i < n; ++i) {
            out[2 * i] = vr[j * n + i];
            out[2 * i + 1] = sign * vr[(j + 1) * n + i];
        }
    }

    PyObject* result = PyTuple_Pack(2, value, (PyObject*)vec);
    Py_DECREF(value);
    Py_DECREF(vec);
    return result;
}

static PyMethodDef methods[] = {
    {"dominant", dominant, METH_O, "return the dominant eigenpair of a matrix"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "_eigfast", NULL, -1, methods,
    NULL, NULL, NULL, NULL
};

PyMODINIT_FUNC PyInit__eigfast(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
