#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <string.h>

typedef long long lapack_int64;
extern void scipy_dgeev_64_(
    const char* jobvl, const char* jobvr, const lapack_int64* n,
    double* a, const lapack_int64* lda, double* wr, double* wi,
    double* vl, const lapack_int64* ldvl, double* vr, const lapack_int64* ldvr,
    double* work, const lapack_int64* lwork, lapack_int64* info);
extern void scipy_zgesv_64_(
    const lapack_int64* n, const lapack_int64* nrhs,
    double* a, const lapack_int64* lda, lapack_int64* ipiv,
    double* b, const lapack_int64* ldb, lapack_int64* info);

#define MAX_N 64
#define COMPLEX_MUL(ar,ai,br,bi,cr,ci) do { double tr=(ar)*(br)-(ai)*(bi); double ti=(ar)*(bi)+(ai)*(br); (cr)=tr; (ci)=ti; } while(0)

static int close_enough(const double* src, npy_intp n, const double* v, double lr, double li) {
    const double atol = 1e-8, rtol = 1e-5;
    for (npy_intp i=0; i<n; ++i) {
        double rr = -lr*v[2*i] + li*v[2*i+1];
        double ri = -lr*v[2*i+1] - li*v[2*i];
        for (npy_intp j=0; j<n; ++j) {
            double ar = src[i*n+j];
            rr += ar*v[2*j];
            ri += ar*v[2*j+1];
        }
        double res = hypot(rr, ri);
        double lamv = hypot(lr*v[2*i] - li*v[2*i+1], lr*v[2*i+1] + li*v[2*i]);
        if (!(res <= atol + rtol*lamv)) return 0;
    }
    return 1;
}

static PyObject* dominant(PyObject* self, PyObject* arg) {
    PyArrayObject* arr = (PyArrayObject*)PyArray_FROM_OTF(
        arg, NPY_DOUBLE, NPY_ARRAY_C_CONTIGUOUS | NPY_ARRAY_ALIGNED);
    if (arr == NULL) return NULL;
    if (PyArray_NDIM(arr) != 2 || PyArray_DIM(arr,0) != PyArray_DIM(arr,1)) {
        Py_DECREF(arr); PyErr_SetString(PyExc_ValueError, "expected a square matrix"); return NULL;
    }
    npy_intp n = PyArray_DIM(arr,0);
    if (n < 1 || n > MAX_N) {
        Py_DECREF(arr); PyErr_SetString(PyExc_ValueError, "unsupported matrix size"); return NULL;
    }
    const double* src = (const double*)PyArray_DATA(arr);
    double a[MAX_N*MAX_N], orig[MAX_N*MAX_N];
    for (npy_intp j=0; j<n; ++j) for (npy_intp i=0; i<n; ++i) {
        double x = src[i*n+j]; a[j*n+i] = x; orig[j*n+i] = x;
    }

    double wr[MAX_N], wi[MAX_N], vr[MAX_N*MAX_N], vl[1], work[8192];
    lapack_int64 nn=(lapack_int64)n, lda=nn, ldvl=1, ldvr=nn, lwork=8192, info=0;
    scipy_dgeev_64_("N","N",&nn,a,&lda,wr,wi,vl,&ldvl,vr,&ldvr,work,&lwork,&info);
    if (info != 0) { Py_DECREF(arr); PyErr_SetString(PyExc_RuntimeError,"LAPACK dgeev failed"); return NULL; }
    npy_intp best=0; double bestabs2=wr[0]*wr[0]+wi[0]*wi[0];
    for (npy_intp i=1;i<n;++i) { double x=wr[i]*wr[i]+wi[i]*wi[i]; if (x>bestabs2) {bestabs2=x;best=i;} }
    double lr=wr[best], li=wi[best];

    double v[2*MAX_N], b[2*MAX_N], m[2*MAX_N*MAX_N];
    lapack_int64 ipiv[MAX_N];

    int success = 0;
    for (int attempt=0; attempt<2 && !success; ++attempt) {
        for (npy_intp j=0;j<n;++j) for (npy_intp i=0;i<n;++i) {
            npy_intp p = j*n+i;
            m[2*p] = orig[p] - ((i==j)?lr:0.0);
            m[2*p+1] = (i==j)?-li:0.0;
        }
        if (attempt==0) {
            for (npy_intp i=0;i<n;++i) {
                b[2*i] = sin(0.713*(double)(i+1)) + 0.4;
                b[2*i+1] = cos(0.371*(double)(i+1)) + 0.3;
            }
        } else {
            memcpy(b, v, 2*n*sizeof(double));
        }
        lapack_int64 nrhs=1, ldb=nn, zinfo=0;
        scipy_zgesv_64_(&nn,&nrhs,m,&lda,ipiv,b,&ldb,&zinfo);
        if (zinfo != 0) break;
        double nrm=0.0;
        for (npy_intp i=0;i<n;++i) nrm += b[2*i]*b[2*i] + b[2*i+1]*b[2*i+1];
